module max_priority_subset (input clk, input rst_n, input start, input [7:0] s_i, input [7:0] d_i, input [7:0] p_i, input valid_in, output reg [11:0] result, output reg done); reg [7:0] s_arr [7:0]; reg [7:0] d_arr [7:0]; reg [7:0] p_arr [7:0]; reg [8:0] e_arr [7:0]; reg [11:0] dp_arr [0:8]; reg [1:2] state; reg [2:0] load_count; reg [2:0] sort_pass; reg [2:0] sort_j; reg [2:0] i_dp; reg [2:0] k_dp; reg [11:0] max_k_val; reg done; reg [7:0] s_arr_next [7:0]; reg [7:0] d_arr_next [7:0]; reg [7:0] p_arr_next [7:0]; reg [8:0] e_arr_next [7:0]; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 0; load_count <=0; sort_pass <=0; sort_j <=0; i_dp <=0; k_dp <=0; max_k_val <=0; done <=0; result <=0; s_arr <=0; d_arr <=0; p_arr <=0; e_arr <=0; dp_arr <=0; s_arr_next <=0; d_arr_next <=0; p_arr_next <=0; e_arr_next <=0; end else begin case(state) IDLE: if (start) begin state <= 1; load_count <=0; s_arr <=0; d_arr <=0; p_arr <=0; e_arr <=0; dp_arr <=0; s_arr_next <=0; d_arr_next <=0; p_arr_next <=0; e_arr_next <=0; end else begin state <=0; end break; LOAD: if (valid_in) begin if (load_count <8) begin s_arr[load_count] <= s_i; d_arr[load_count] <= d_i; p_arr[load_count] <= p_i; e_arr[load_count] <= s_i + d_i; load_count <= load_count +1; end end if (load_count ==8) begin state <=2; sort_pass <=0; sort_j <=0; end break; SORT: s_arr_next = s_arr; d_arr_next = d_arr; p_arr_next = p_arr; e_arr_next = e_arr; if (state ==2) begin if (sort_pass <7) begin if (sort_j < (7 - sort_pass)) begin if (e_arr[sort_j] > e_arr[sort_j+1]) begin s_arr_next[sort_j] = s_arr[sort_j+1]; s_arr_next[sort_j+1] = s_arr[sort_j]; d_arr_next[sort_j] = d_arr[sort_j+1]; d_arr_next[sort_j+1] = d_arr[sort_j]; p_arr_next[sort_j] = p_arr[sort_j+1]; p_arr_next[sort_j+1] = p_arr[sort_j]; e_arr_next[sort_j] = e_arr[sort_j+1]; e_arr_next[sort_j+1] = e_arr[sort_j]; end end end else begin sort_j <=0; sort_pass <= sort_pass +1; end end end if (state ==2) begin s_arr <= s_arr_next; d_arr <= d_arr_next; p_arr <= p_arr_next; e_arr <= e_arr_next; end if (state ==2) begin if (sort_pass <7) begin if (sort_j < (7 - sort_pass)) begin sort_j <= sort_j +1; end else begin sort_j <=0; sort_pass <= sort_pass +1; end end else begin state <=3; i_dp <=1; k_dp <=0; max_k_val <=0; end break; DP_COMPUTE: if (i_dp <=8) begin if (k_dp < i_dp) begin if (e_arr[k_dp] <= s_arr[i_dp]) begin if (dp_arr[k_dp] > max_k_val) max_k_val <= dp_arr[k_dp]; end k_dp <= k_dp +1; end else begin dp_arr[i_dp] <= (p_arr[i_dp] + max_k_val) > dp_arr[i_dp-1] ? (p_arr[i_dp] + max_k_val) : dp_arr[i_dp-1]; i_dp <= i_dp +1; k_dp <=0; max_k_val <=0; end end else begin state <=4; end break; FINISH: done <=1; result <= dp_arr[8]; break; default: state <=0; endcase if (state ==0) done <=0; end endmodule